import { useState } from "react";
import { useAuth } from "@/contexts/AuthContext";
import { useChat } from "@/contexts/ChatContext";
import {
  ChatSidebarContainer,
  ChatInputContainer,
  MessageList,
} from "@/components/chat";
import { RightSidebar } from "@/components/RightSidebar";
import { AuthPage } from "@/pages/AuthPage";
import { ChevronLeft, PanelRightOpen } from "lucide-react";

function App() {
  const { isLoggedIn, isLoading: authLoading } = useAuth();
  const { currentChat, messages, isStreaming } = useChat();
  const [isRightSidebarOpen, setIsRightSidebarOpen] = useState(true);

  // Show auth page if not logged in
  if (!isLoggedIn && !authLoading) {
    return <AuthPage />;
  }

  // Show loading state
  if (authLoading) {
    return (
      <div className="fixed inset-0 bg-bg-base flex flex-col items-center justify-center gap-4">
        <div className="w-10 h-10 border-[3px] border-purple-400/30 border-t-purple-500 rounded-full animate-spin" />
        <p className="text-text-secondary">Loading...</p>
      </div>
    );
  }

  const isHomeView = !currentChat && messages.length === 0;

  return (
    <div className="relative h-screen flex overflow-hidden bg-zinc-50">
      {/* Left Sidebar - Chat History */}
      <ChatSidebarContainer />

      {/* Main Content */}
      <div className="flex-1 flex flex-col overflow-hidden min-w-0">
        {isHomeView ? (
          /* Home View */
          <div className="flex-1 flex flex-col items-center justify-center px-6 py-10 overflow-hidden bg-white">
            <div className="mb-8">
              <div className="flex flex-col items-center gap-2">
                <h1 className="font-accent text-4xl font-normal text-text-primary tracking-tighter">
                  Mari berbincang dan berkreasi bersama 🤙
                </h1>
                <p className="text-sm text-text-tertiary mt-1 tracking-wide font-light">
                  Powered by Claude Code and Composio
                </p>
              </div>
            </div>

            <ChatInputContainer variant="home" />
          </div>
        ) : (
          /* Chat View */
          <div className="flex-1 flex h-screen overflow-hidden">
            <div className="flex-1 flex flex-col min-w-0 h-screen overflow-hidden bg-white">
              {/* Chat Header */}
              <div className="flex items-center justify-between px-6 py-3.5 bg-white">
                <h1 className="text-sm font-medium text-text-primary tracking-tight">
                  {currentChat?.title || "New chat"}
                </h1>
                <div className="flex items-center gap-2">
                  <button 
                    onClick={() => setIsRightSidebarOpen(prev => !prev)}
                    className="w-8 h-8 rounded-full bg-zinc-100 flex items-center justify-center hover:bg-zinc-200 transition-colors text-zinc-600"
                    title={isRightSidebarOpen ? "Hide sidebar" : "Show sidebar"}
                  >
                    {isRightSidebarOpen ? (
                      <ChevronLeft className="w-4 h-4" strokeWidth={1.5} />
                    ) : (
                      <PanelRightOpen className="w-4 h-4" strokeWidth={1.5} />
                    )}
                  </button>
                </div>
              </div>

              {/* Messages */}
              <MessageList messages={messages} isStreaming={isStreaming} />

              {/* Input */}
              <ChatInputContainer variant="chat" />
            </div>

            {/* Right Sidebar */}
            {isRightSidebarOpen && <RightSidebar />}
          </div>
        )}
      </div>
    </div>
  );
}

export default App;

export function RightSidebar() {
  return (
    <aside className="w-72 min-w-72 bg-white border-l border-gray-200">
      {/* Empty - reserved for future use */}
    </aside>
  );
}

/**
 * ChatSidebarContainer - Container component
 * 
 * Connects to context and passes data to presentational ChatSidebar.
 */
import { useState } from 'react';
import { useChat } from '@/contexts/ChatContext';
import { useAuth } from '@/contexts/AuthContext';
import { ChatSidebar } from './ChatSidebar';
import { SettingsModal } from '../SettingsModal';

export function ChatSidebarContainer() {
  const { chats, currentChat, loadChat, createNewChat, deleteChat } = useChat();
  const { user, currentWorkspace, workspaces, switchWorkspace, createWorkspace } = useAuth();
  const [isSettingsOpen, setIsSettingsOpen] = useState(false);

  return (
    <>
      <ChatSidebar
        user={user}
        currentWorkspace={currentWorkspace}
        workspaces={workspaces}
        onSwitchWorkspace={switchWorkspace}
        onCreateWorkspace={createWorkspace}
        chats={chats}
        currentChatId={currentChat?.id ?? null}
        onLoadChat={loadChat}
        onCreateChat={createNewChat}
        onDeleteChat={deleteChat}
        onOpenSettings={() => setIsSettingsOpen(true)}
      />

      <SettingsModal
        isOpen={isSettingsOpen}
        onClose={() => setIsSettingsOpen(false)}
      />
    </>
  );
}

/* Design System Tokens - Based on Syle Digital Marketer */

:root {
  /* Colors - Purple Scale */
  --purple-400: #c084fc;
  --purple-500: #a855f7;
  --purple-600: #9333ea;

  /* Colors - Neutrals */
  --primary-dark: #111111;
  --background: #fafafa;
  --surface: #ffffff;
  --surface-secondary: #f9fafb;

  /* Colors - Text */
  --text-primary: #101828;
  --text-secondary: #4a5565;
  --text-tertiary: #6a7282;

  /* Colors - Borders */
  --border-light: #f3f4f6;
  --border-default: #e5e7eb;

  /* Colors - Glass Effects */
  --glass-surface: rgba(255, 255, 255, 0.4);
  --glass-border: rgba(255, 255, 255, 0.6);
  --glass-surface-strong: rgba(255, 255, 255, 0.5);

  /* Colors - Gradients */
  --gradient-purple: linear-gradient(135deg, #a855f7 0%, #9333ea 100%);
  --gradient-purple-full: linear-gradient(
    135deg,
    rgba(168, 85, 247, 1) 0%,
    rgba(166, 82, 246, 1) 10%,
    rgba(164, 79, 244, 1) 20%,
    rgba(162, 76, 243, 1) 30%,
    rgba(159, 73, 242, 1) 40%,
    rgba(157, 69, 241, 1) 50%,
    rgba(155, 66, 239, 1) 60%,
    rgba(153, 62, 238, 1) 70%,
    rgba(151, 59, 237, 1) 80%,
    rgba(149, 55, 235, 1) 90%,
    rgba(147, 51, 234, 1) 100%
  );
  --gradient-surface: linear-gradient(180deg, #f9fafb 0%, #ffffff 100%);
  --gradient-background: linear-gradient(
    180deg,
    rgba(168, 85, 247, 0.6) 0%,
    rgba(168, 85, 247, 0.15) 50%,
    rgba(250, 250, 250, 1) 100%
  );

  /* Typography - Font Families */
  --font-primary:
    "Inter", -apple-system, BlinkMacSystemFont, "Segoe UI", sans-serif;
  --font-accent: "Playfair Display", Georgia, serif;

  /* Typography - Sizes (Perfect Fourth scale, base: 16px) */
  --text-xs: 0.875rem;      /* 14px - minimum readable */
  --text-sm: 0.9375rem;     /* 15px - UI labels */
  --text-base: 1rem;        /* 16px - body text */
  --text-lg: 1.1875rem;     /* 19px - lead text */
  --text-xl: 1.4375rem;     /* 23px - h4 */
  --text-2xl: 1.75rem;      /* 28px - h3 */
  --text-3xl: 2.0625rem;    /* 33px - h2 */
  --text-4xl: 2.5rem;       /* 40px - h1 */

  /* Typography - Line Heights */
  --leading-tight: 1em;
  --leading-snug: 1.111;
  --leading-normal: 1.375;
  --leading-relaxed: 1.5;
  --leading-loose: 1.625;

  /* Typography - Letter Spacing */
  --tracking-tight: -0.05em;
  --tracking-normal: -0.025em;
  --tracking-wide: 0.05em;

  /* Spacing Scale (base: 7px) */
  --space-1: 0.4375rem; /* 7px */
  --space-2: 0.875rem; /* 14px */
  --space-3: 1.3125rem; /* 21px */
  --space-4: 1.75rem; /* 28px */
  --space-5: 2.1875rem; /* 35px */
  --space-6: 2.625rem; /* 42px */
  --space-8: 3.5rem; /* 56px */
  --space-14: 6.125rem; /* 98px */

  /* Border Radius */
  --radius-sm: 0.25rem;
  --radius-md: 0.5rem;
  --radius-lg: 1.3125rem; /* 21px - card radius */
  --radius-full: 9999px;

  /* Shadows */
  --shadow-subtle: 0px 2px 10px 0px rgba(0, 0, 0, 0.02);
  --shadow-sm:
    0px 1px 2px -1px rgba(0, 0, 0, 0.1), 0px 1px 3px 0px rgba(0, 0, 0, 0.1);
  --shadow-md: 0px 8px 30px 0px rgba(0, 0, 0, 0.06);
  --shadow-purple: 0px 8px 25px 0px rgba(168, 85, 247, 0.35);
  --shadow-glass:
    0px 4px 6px -4px rgba(0, 0, 0, 0.1), 0px 10px 15px -3px rgba(0, 0, 0, 0.1);

  /* Effects */
  --blur-sm: 80px;
  --blur-lg: 128px;

  /* Transitions */
  --transition-fast: 150ms cubic-bezier(0.4, 0, 0.2, 1);
  --transition-base: 200ms cubic-bezier(0.4, 0, 0.2, 1);
  --transition-slow: 300ms cubic-bezier(0.4, 0, 0.2, 1);
}

/* Typography Utilities */
.font-primary {
  font-family: var(--font-primary);
}

.font-accent {
  font-family: var(--font-accent);
}

/* Glass Morphism Utility */
.glass {
  background: var(--glass-surface);
  border: 1px solid var(--glass-border);
  backdrop-filter: blur(10px);
  -webkit-backdrop-filter: blur(10px);
}

.glass-strong {
  background: var(--glass-surface-strong);
  border: 1px solid var(--border-default);
  backdrop-filter: blur(10px);
  -webkit-backdrop-filter: blur(10px);
}

/* Gradient Utilities */
.gradient-purple {
  background: var(--gradient-purple-full);
}

.gradient-surface {
  background: var(--gradient-surface);
}

/**
 * MarkdownRenderer - Professional markdown rendering for chat messages
 *
 * Based on best practices from:
 * - Open WebUI (content rendering pipeline)
 * - Lobe Chat (shadcn-prose integration)
 * - Jan (RenderMarkdown.tsx composition)
 *
 * Features:
 * - GitHub Flavored Markdown (tables, strikethrough, task lists)
 * - Syntax highlighting with Prism (all languages)
 * - Copy-to-clipboard for code blocks
 * - Responsive tables with overflow
 * - Proper typography hierarchy
 * - Dark mode support
 */
import { useState, useCallback, memo } from "react";
import ReactMarkdown from "react-markdown";
import remarkGfm from "remark-gfm";
import { Prism as SyntaxHighlighter } from "react-syntax-highlighter";
import {
  vscDarkPlus,
  oneLight,
} from "react-syntax-highlighter/dist/esm/styles/prism";
import { Copy, Check } from "lucide-react";

interface MarkdownRendererProps {
  content: string;
  className?: string;
}

interface CodeBlockProps {
  language: string;
  code: string;
}

// Copy-to-clipboard code block component
const CodeBlock = memo(function CodeBlock({ language, code }: CodeBlockProps) {
  const [copied, setCopied] = useState(false);

  const handleCopy = useCallback(async () => {
    try {
      await navigator.clipboard.writeText(code);
      setCopied(true);
      setTimeout(() => setCopied(false), 2000);
    } catch (err) {
      console.error("Failed to copy:", err);
    }
  }, [code]);

  return (
    <div className="code-block-wrapper my-4 rounded-lg overflow-hidden border border-black/10">
      {/* Header with language and copy button */}
      <div className="flex items-center justify-between px-3 py-2 bg-[#f6f8fa] border-b border-black/10">
        <span className="text-xs font-normal text-zinc-600 uppercase tracking-wide">
          {language || "text"}
        </span>
        <button
          onClick={handleCopy}
          className="flex items-center gap-1.5 px-2 py-1 rounded text-xs font-normal text-zinc-600 
                     hover:bg-zinc-200/50 hover:text-zinc-900 transition-colors"
          aria-label={copied ? "Copied!" : "Copy code"}
        >
          {copied ? (
            <>
              <Check className="w-3.5 h-3.5 text-emerald-600" />
              <span className="text-emerald-600">Copied!</span>
            </>
          ) : (
            <>
              <Copy className="w-3.5 h-3.5" />
              <span>Copy</span>
            </>
          )}
        </button>
      </div>

      {/* Code content */}
      <div className="max-h-[600px] overflow-auto">
        <SyntaxHighlighter
          language={language || "text"}
          style={oneLight}
          customStyle={{
            margin: 0,
            padding: "1rem",
            fontSize: "0.9375rem", /* 15px */
            lineHeight: "1.6",
            background: "#ffffff",
          }}
          codeTagProps={{
            style: {
              fontFamily:
                'ui-monospace, SFMono-Regular, "SF Mono", Menlo, Consolas, monospace',
            },
          }}
        >
          {code}
        </SyntaxHighlighter>
      </div>
    </div>
  );
});

// Generate heading ID for anchor links
function generateHeadingId(children: React.ReactNode): string {
  const text = String(children).toLowerCase();
  return text
    .replace(/[^\w\s-]/g, "")
    .replace(/\s+/g, "-")
    .replace(/-+/g, "-")
    .trim();
}

export const MarkdownRenderer = memo(function MarkdownRenderer({
  content,
  className = "",
}: MarkdownRendererProps) {
  if (!content) return null;

  return (
    <div className={className}>
      <ReactMarkdown
        remarkPlugins={[remarkGfm]}
        components={{
          // Headings with anchor IDs
          h1: ({ children, ...props }) => {
            const id = generateHeadingId(children);
            return (
              <h1
                id={id}
                className="text-3xl font-semibold leading-tight mt-8 mb-4 text-zinc-900 tracking-tight"
                {...props}
              >
                {children}
              </h1>
            );
          },
          h2: ({ children, ...props }) => {
            const id = generateHeadingId(children);
            return (
              <h2
                id={id}
                className="text-2xl font-semibold leading-tight mt-6 mb-3 text-zinc-900 tracking-tight border-b border-zinc-200 pb-2"
                {...props}
              >
                {children}
              </h2>
            );
          },
          h3: ({ children, ...props }) => {
            const id = generateHeadingId(children);
            return (
              <h3
                id={id}
                className="text-xl font-medium leading-tight mt-5 mb-3 text-zinc-900 tracking-tight"
                {...props}
              >
                {children}
              </h3>
            );
          },
          h4: ({ children, ...props }) => (
            <h4
              className="text-lg font-medium leading-tight mt-4 mb-2 text-zinc-900"
              {...props}
            >
              {children}
            </h4>
          ),
          h5: ({ children, ...props }) => (
            <h5
              className="text-base font-medium leading-tight mt-3 mb-2 text-zinc-900"
              {...props}
            >
              {children}
            </h5>
          ),
          h6: ({ children, ...props }) => (
            <h6
              className="text-sm font-semibold leading-tight mt-3 mb-2 text-zinc-600 uppercase tracking-wider"
              {...props}
            >
              {children}
            </h6>
          ),

          // Paragraphs - light weight as base
          p: ({ children, ...props }) => (
            <p
              className="my-4 text-base leading-[1.7] text-text-primary font-normal"
              {...props}
            >
              {children}
            </p>
          ),

          // Lists - consistent with paragraph styling
          ul: ({ children, ...props }) => (
            <ul className="my-3 pl-5 list-disc space-y-1.5" {...props}>
              {children}
            </ul>
          ),
          ol: ({ children, ...props }) => (
            <ol className="my-3 pl-5 list-decimal space-y-1.5" {...props}>
              {children}
            </ol>
          ),
          li: ({ children, ...props }) => (
            <li
              className="text-base leading-[1.7] text-text-primary marker:text-text-tertiary font-normal"
              {...props}
            >
              {children}
            </li>
          ),

          // Task lists (GFM)
          input: ({ checked, ...props }) => (
            <input
              type="checkbox"
              checked={checked}
              readOnly
              className="mr-2 h-3.5 w-3.5 rounded border-zinc-300 text-zinc-900 focus:ring-zinc-900"
              {...props}
            />
          ),

          // Code blocks and inline code
          code: ({ className, children, ...props }) => {
            const match = /language-(\w+)/.exec(className || "");
            const language = match ? match[1] : "";
            const code = String(children).replace(/\n$/, "");

            // Block code (has language or multiple lines)
            if (language || code.includes("\n")) {
              return <CodeBlock language={language} code={code} />;
            }

            // Inline code
            return (
              <code
                className="px-1.5 py-0.5 text-[0.85em] font-mono rounded bg-surface-secondary text-text-primary border border-border-light"
                {...props}
              >
                {children}
              </code>
            );
          },

          pre: ({ children }) => <>{children}</>,

          // Blockquotes
          blockquote: ({ children, ...props }) => (
            <blockquote
              className="my-3 pl-4 border-l-2 border-purple-500 italic text-text-secondary bg-purple-50/30 py-2 rounded-r"
              {...props}
            >
              {children}
            </blockquote>
          ),

          // Links
          a: ({ href, children, ...props }) => (
            <a
              href={href}
              className="text-coral hover:underline underline-offset-2 decoration-coral/50"
              target={href?.startsWith("http") ? "_blank" : undefined}
              rel={href?.startsWith("http") ? "noopener noreferrer" : undefined}
              {...props}
            >
              {children}
            </a>
          ),

          // Images
          img: ({ src, alt, ...props }) => (
            <img
              src={src}
              alt={alt}
              className="my-4 max-w-full h-auto rounded-lg shadow-sm"
              loading="lazy"
              {...props}
            />
          ),

          // Horizontal rule
          hr: () => <hr className="my-6 border-zinc-200" />,

          // Tables (GFM)
          table: ({ children, ...props }) => (
            <div className="my-4 overflow-x-auto rounded-lg border border-zinc-200">
              <table
                className="min-w-full divide-y divide-zinc-200 text-sm"
                {...props}
              >
                {children}
              </table>
            </div>
          ),
          thead: ({ children, ...props }) => (
            <thead className="bg-zinc-50" {...props}>
              {children}
            </thead>
          ),
          tbody: ({ children, ...props }) => (
            <tbody className="divide-y divide-zinc-200 bg-white" {...props}>
              {children}
            </tbody>
          ),
          tr: ({ children, ...props }) => (
            <tr className="hover:bg-zinc-50/50 transition-colors" {...props}>
              {children}
            </tr>
          ),
          th: ({ children, ...props }) => (
            <th
              className="px-4 py-3 text-left text-xs font-medium text-zinc-600 uppercase tracking-wider"
              {...props}
            >
              {children}
            </th>
          ),
          td: ({ children, ...props }) => (
            <td
              className="px-4 py-3 text-zinc-800 whitespace-nowrap"
              {...props}
            >
              {children}
            </td>
          ),

          // Strikethrough (GFM)
          del: ({ children, ...props }) => (
            <del className="line-through text-zinc-500" {...props}>
              {children}
            </del>
          ),

          // Strong and emphasis - decreased by one level
          strong: ({ children, ...props }) => (
            <strong className="font-medium text-zinc-900" {...props}>
              {children}
            </strong>
          ),
          em: ({ children, ...props }) => (
            <em className="italic" {...props}>
              {children}
            </em>
          ),
        }}
      >
        {content}
      </ReactMarkdown>
    </div>
  );
});

@import "./styles/design-tokens.css";

@tailwind base;
@tailwind components;
@tailwind utilities;

@layer base {
  :root {
    --font-size: 16px;
    --background: #ffffff;
    --foreground: oklch(0.145 0 0);
    --card: #ffffff;
    --card-foreground: oklch(0.145 0 0);
    --popover: oklch(1 0 0);
    --popover-foreground: oklch(0.145 0 0);
    --primary: #030213;
    --primary-foreground: oklch(1 0 0);
    --secondary: oklch(0.95 0.0058 264.53);
    --secondary-foreground: #030213;
    --muted: #ececf0;
    --muted-foreground: #717182;
    --accent: #e9ebef;
    --accent-foreground: #030213;
    --destructive: #d4183d;
    --destructive-foreground: #ffffff;
    --border: rgba(0, 0, 0, 0.1);
    --input: transparent;
    --input-background: #f3f3f5;
    --switch-background: #cbced4;
    --font-weight-medium: 500;
    --font-weight-normal: 400;
    --font-weight-light: 300;
    --ring: oklch(0.708 0 0);
    --chart-1: oklch(0.646 0.222 41.116);
    --chart-2: oklch(0.6 0.118 184.704);
    --chart-3: oklch(0.398 0.07 227.392);
    --chart-4: oklch(0.828 0.189 84.429);
    --chart-5: oklch(0.769 0.188 70.08);
    --radius: 0.625rem;
    --sidebar: oklch(0.985 0 0);
    --sidebar-foreground: oklch(0.145 0 0);
    --sidebar-primary: #030213;
    --sidebar-primary-foreground: oklch(0.985 0 0);
    --sidebar-accent: oklch(0.97 0 0);
    --sidebar-accent-foreground: oklch(0.205 0 0);
    --sidebar-border: oklch(0.922 0 0);
    --sidebar-ring: oklch(0.708 0 0);

    /* Map to Tailwind color variables */
    --color-background: var(--background);
    --color-foreground: var(--foreground);
    --color-card: var(--card);
    --color-card-foreground: var(--card-foreground);
    --color-popover: var(--popover);
    --color-popover-foreground: var(--popover-foreground);
    --color-primary: var(--primary);
    --color-primary-foreground: var(--primary-foreground);
    --color-secondary: var(--secondary);
    --color-secondary-foreground: var(--secondary-foreground);
    --color-muted: var(--muted);
    --color-muted-foreground: var(--muted-foreground);
    --color-accent: var(--accent);
    --color-accent-foreground: var(--accent-foreground);
    --color-destructive: var(--destructive);
    --color-destructive-foreground: var(--destructive-foreground);
    --color-border: var(--border);
    --color-input: var(--input);
    --color-input-background: var(--input-background);
    --color-switch-background: var(--switch-background);
    --color-ring: var(--ring);
    --color-chart-1: var(--chart-1);
    --color-chart-2: var(--chart-2);
    --color-chart-3: var(--chart-3);
    --color-chart-4: var(--chart-4);
    --color-chart-5: var(--chart-5);
    --radius-sm: calc(var(--radius) - 4px);
    --radius-md: calc(var(--radius) - 2px);
    --radius-lg: var(--radius);
    --radius-xl: calc(var(--radius) + 4px);
    --color-sidebar: var(--sidebar);
    --color-sidebar-foreground: var(--sidebar-foreground);
    --color-sidebar-primary: var(--sidebar-primary);
    --color-sidebar-primary-foreground: var(--sidebar-primary-foreground);
    --color-sidebar-accent: var(--sidebar-accent);
    --color-sidebar-accent-foreground: var(--sidebar-accent-foreground);
    --color-sidebar-border: var(--sidebar-border);
    --color-sidebar-ring: var(--sidebar-ring);
  }

  .dark {
    --background: oklch(0.145 0 0);
    --foreground: oklch(0.985 0 0);
    --card: oklch(0.145 0 0);
    --card-foreground: oklch(0.985 0 0);
    --popover: oklch(0.145 0 0);
    --popover-foreground: oklch(0.985 0 0);
    --primary: oklch(0.985 0 0);
