@layer utilities {
  .animate-fade-in {
    animation: fadeIn 0.2s ease-out;
  }

  @keyframes fadeIn {
    from {
      opacity: 0;
      transform: translateY(8px);
    }
    to {
      opacity: 1;
      transform: translateY(0);
    }
  }

  .animate-pulse-slow {
    animation: pulse-slow 2s ease-in-out infinite;
  }

  @keyframes pulse-slow {
    0%,
    100% {
      opacity: 1;
    }
    50% {
      opacity: 0.5;
    }
  }

  /* Streaming cursor blink */
  .animate-cursor-blink {
    animation: cursorBlink 0.8s step-end infinite;
  }

  @keyframes cursorBlink {
    0%,
    50% {
      opacity: 1;
    }
    51%,
    100% {
      opacity: 0;
    }
  }

  /* Shimmer loading effect */
  .animate-shimmer {
    animation: shimmer 1.5s ease-in-out infinite;
    background: linear-gradient(
      90deg,
      oklch(0.97 0 0) 0%,
      oklch(0.99 0 0) 50%,
      oklch(0.97 0 0) 100%
    );
    background-size: 200% 100%;
  }

  @keyframes shimmer {
    0% {
      background-position: 200% 0;
    }
    100% {
      background-position: -200% 0;
    }
  }

  /* Smooth streaming text - optimized for performance */
  .streaming-content {
    contain: content;
    will-change: contents;
    /* Text naturally accumulates without animation - modern approach */
    /* Only apply subtle fade to newly added content via React */
    animation: none;
  }

  /* Subtle fade-in for streaming content updates */
  .animate-fade-in-subtle {
    animation: fadeInSubtle 0.3s ease-out;
  }

  @keyframes fadeInSubtle {
    from {
      opacity: 0.7;
    }
    to {
      opacity: 1;
    }
  }

  .streaming-markdown {
    contain: content;
  }

  .streaming-cursor {
    display: inline-block;
    width: 2px;
    height: 1em;
    background-color: currentColor;
    margin-left: 2px;
    vertical-align: text-bottom;
    animation: cursorBlink 0.8s step-end infinite;
  }

  /* Coral-colored streaming cursor */
  .streaming-cursor-coral {
    display: inline-block;
    width: 2px;
    height: 1em;
    background-color: #ff6b6b;
    margin-left: 2px;
    vertical-align: text-bottom;
    animation: cursorBlink 0.8s step-end infinite;
  }

  /* ===== Flowtoken-style Character Animation ===== */

  /* Flowtoken animation keyframes */
  @keyframes ft-fadeIn {
    from {
      opacity: 0;
    }
    to {
      opacity: 1;
    }
  }

  @keyframes ft-slideUp {
    from {
      opacity: 0;
      transform: translateY(10px);
    }
    to {
      opacity: 1;
      transform: translateY(0);
    }
  }

  @keyframes ft-blurIn {
    0% {
      opacity: 0;
      filter: blur(10px);
    }
    100% {
      opacity: 1;
      filter: blur(0);
    }
  }

  @keyframes ft-dropIn {
    0% {
      opacity: 0;
      transform: translateY(-15px);
    }
    100% {
      opacity: 1;
      transform: translateY(0);
    }
  }

  @keyframes ft-wave {
    0% {
      opacity: 0;
      transform: translateY(5px);
    }
    50% {
      opacity: 1;
      transform: translateY(-2px);
    }
    100% {
      transform: translateY(0);
    }
  }

  @keyframes ft-highlight {
    0% {
      background-color: rgba(255, 200, 100, 0.5);
    }
    100% {
      background-color: transparent;
    }
  }

  /* Container for animated markdown during streaming */
  .streaming-markdown {
    contain: content;
    will-change: contents;
  }

  /* Each animated character gets this class */
  .char-animated,
  .char-sp,
  .ft-char,
  .fc {
    display: inline;
    animation: charFadeInUp 0.8s ease-in-out both;
  }

  /* Fade in up animation - inspired by Flowtoken */
  @keyframes charFadeInUp {
    from {
      opacity: 0;
      transform: translateY(4px);
    }
    to {
      opacity: 1;
      transform: translateY(0);
    }
  }

  /* Alternative animations (Flowtoken provides these) */

  /* Blur in effect */
  .char-animated-blur {
    animation: charBlurIn 0.8s ease-in-out both;
  }

  @keyframes charBlurIn {
    from {
      opacity: 0;
      filter: blur(8px);
    }
    to {
      opacity: 1;
      filter: blur(0);
    }
  }

  /* Drop in effect */
  .char-animated-drop {
    animation: charDropIn 0.8s ease-in-out both;
  }

  @keyframes charDropIn {
    from {
      opacity: 0;
      transform: translateY(-12px);
    }
    to {
      opacity: 1;
      transform: translateY(0);
    }
  }

  /* Wave effect */
  .char-animated-wave {
    animation: charWave 0.8s ease-in-out both;
  }

  @keyframes charWave {
    0%,
    100% {
      transform: translateY(0);
    }
    25% {
      transform: translateY(-3px);
    }
    50% {
      transform: translateY(0);
    }
    75% {
      transform: translateY(3px);
    }
  }

  /* Highlight effect */
  .char-animated-highlight {
    animation: charHighlight 0.8s ease-in-out both;
  }

  @keyframes charHighlight {
    from {
      background-color: rgba(255, 107, 107, 0.3);
    }
    to {
      background-color: transparent;
    }
  }

  /* For completed messages - fade in the whole block */
  .animate-fade-in-up {
    animation: smoothFadeInUp 0.8s ease-in-out;
  }

  @keyframes smoothFadeInUp {
    from {
      opacity: 0;
      transform: translateY(8px);
    }
    to {
      opacity: 1;
      transform: translateY(0);
    }
  }

  /* Spinner rotation */
  .animate-spin-slow {
    animation: spin 1.5s linear infinite;
  }

  @keyframes spin {
    from {
      transform: rotate(0deg);
    }
    to {
      transform: rotate(360deg);
    }
  }
}

/* Design System Tokens - Based on Syle Digital Marketer */

:root {
  /* Colors - Purple Scale */
  --purple-400: #c084fc;
  --purple-500: #a855f7;
  --purple-600: #9333ea;

  /* Colors - Neutrals */
  --primary-dark: #111111;
  --background: #fafafa;
  --surface: #ffffff;
  --surface-secondary: #f9fafb;

  /* Colors - Text */
  --text-primary: #101828;
  --text-secondary: #4a5565;
  --text-tertiary: #6a7282;

  /* Colors - Borders */
  --border-light: #f3f4f6;
  --border-default: #e5e7eb;

  /* Colors - Glass Effects */
  --glass-surface: rgba(255, 255, 255, 0.4);
  --glass-border: rgba(255, 255, 255, 0.6);
  --glass-surface-strong: rgba(255, 255, 255, 0.5);

  /* Colors - Gradients */
  --gradient-purple: linear-gradient(135deg, #a855f7 0%, #9333ea 100%);
  --gradient-purple-full: linear-gradient(
    135deg,
    rgba(168, 85, 247, 1) 0%,
    rgba(166, 82, 246, 1) 10%,
    rgba(164, 79, 244, 1) 20%,
    rgba(162, 76, 243, 1) 30%,
    rgba(159, 73, 242, 1) 40%,
    rgba(157, 69, 241, 1) 50%,
    rgba(155, 66, 239, 1) 60%,
    rgba(153, 62, 238, 1) 70%,
    rgba(151, 59, 237, 1) 80%,
    rgba(149, 55, 235, 1) 90%,
    rgba(147, 51, 234, 1) 100%
  );
  --gradient-surface: linear-gradient(180deg, #f9fafb 0%, #ffffff 100%);
  --gradient-background: linear-gradient(
    180deg,
    rgba(168, 85, 247, 0.6) 0%,
    rgba(168, 85, 247, 0.15) 50%,
    rgba(250, 250, 250, 1) 100%
  );

  /* Typography - Font Families */
  --font-primary:
    "Inter", -apple-system, BlinkMacSystemFont, "Segoe UI", sans-serif;
  --font-accent: "Playfair Display", Georgia, serif;

  /* Typography - Sizes (Gentle scale, base: 15px) */
  --text-xs: 0.8125rem;      /* 13px - captions, labels */
  --text-sm: 0.875rem;       /* 14px - small UI text */
  --text-base: 0.9375rem;    /* 15px - body text */
  --text-lg: 1rem;           /* 16px - h5, lead text */
  --text-xl: 1.125rem;       /* 18px - h4 */
  --text-2xl: 1.25rem;       /* 20px - h3 */
  --text-3xl: 1.375rem;      /* 22px - h2 */
  --text-4xl: 1.5rem;        /* 24px - h1 */

  /* Typography - Line Heights */
  --leading-tight: 1em;
  --leading-snug: 1.111;
  --leading-normal: 1.375;
  --leading-relaxed: 1.5;
  --leading-loose: 1.625;

  /* Typography - Letter Spacing */
  --tracking-tight: -0.05em;
  --tracking-normal: -0.025em;
  --tracking-wide: 0.05em;

  /* Spacing Scale (base: 7px) */
  --space-1: 0.4375rem; /* 7px */
  --space-2: 0.875rem; /* 14px */
  --space-3: 1.3125rem; /* 21px */
  --space-4: 1.75rem; /* 28px */
  --space-5: 2.1875rem; /* 35px */
  --space-6: 2.625rem; /* 42px */
  --space-8: 3.5rem; /* 56px */
  --space-14: 6.125rem; /* 98px */

  /* Border Radius */
  --radius-sm: 0.25rem;
  --radius-md: 0.5rem;
  --radius-lg: 1.3125rem; /* 21px - card radius */
  --radius-full: 9999px;

  /* Shadows */
  --shadow-subtle: 0px 2px 10px 0px rgba(0, 0, 0, 0.02);
  --shadow-sm:
    0px 1px 2px -1px rgba(0, 0, 0, 0.1), 0px 1px 3px 0px rgba(0, 0, 0, 0.1);
  --shadow-md: 0px 8px 30px 0px rgba(0, 0, 0, 0.06);
  --shadow-purple: 0px 8px 25px 0px rgba(168, 85, 247, 0.35);
  --shadow-glass:
    0px 4px 6px -4px rgba(0, 0, 0, 0.1), 0px 10px 15px -3px rgba(0, 0, 0, 0.1);

  /* Effects */
  --blur-sm: 80px;
  --blur-lg: 128px;

  /* Transitions */
  --transition-fast: 150ms cubic-bezier(0.4, 0, 0.2, 1);
  --transition-base: 200ms cubic-bezier(0.4, 0, 0.2, 1);
  --transition-slow: 300ms cubic-bezier(0.4, 0, 0.2, 1);
}

/* Typography Utilities */
.font-primary {
  font-family: var(--font-primary);
}

.font-accent {
  font-family: var(--font-accent);
}

/* Glass Morphism Utility */
.glass {
  background: var(--glass-surface);
  border: 1px solid var(--glass-border);
  backdrop-filter: blur(10px);
  -webkit-backdrop-filter: blur(10px);
}

.glass-strong {
  background: var(--glass-surface-strong);
  border: 1px solid var(--border-default);
  backdrop-filter: blur(10px);
  -webkit-backdrop-filter: blur(10px);
}

/* Gradient Utilities */
.gradient-purple {
  background: var(--gradient-purple-full);
}

.gradient-surface {
  background: var(--gradient-surface);
}

/**
 * MarkdownRenderer - Professional markdown rendering for chat messages
 *
 * Based on best practices from:
 * - Open WebUI (content rendering pipeline)
 * - Lobe Chat (shadcn-prose integration)
 * - Jan (RenderMarkdown.tsx composition)
 *
 * Features:
 * - GitHub Flavored Markdown (tables, strikethrough, task lists)
 * - Syntax highlighting with Prism (all languages)
 * - Copy-to-clipboard for code blocks
 * - Responsive tables with overflow
 * - Proper typography hierarchy
 * - Dark mode support
 */
import { useState, useCallback, memo } from "react";
import ReactMarkdown from "react-markdown";
import remarkGfm from "remark-gfm";
import { Prism as SyntaxHighlighter } from "react-syntax-highlighter";
import {
  vscDarkPlus,
  oneLight,
} from "react-syntax-highlighter/dist/esm/styles/prism";
import { Copy, Check } from "lucide-react";

interface MarkdownRendererProps {
  content: string;
  className?: string;
}

interface CodeBlockProps {
  language: string;
  code: string;
}

// Copy-to-clipboard code block component
const CodeBlock = memo(function CodeBlock({ language, code }: CodeBlockProps) {
  const [copied, setCopied] = useState(false);

  const handleCopy = useCallback(async () => {
    try {
      await navigator.clipboard.writeText(code);
      setCopied(true);
      setTimeout(() => setCopied(false), 2000);
    } catch (err) {
      console.error("Failed to copy:", err);
    }
  }, [code]);

  return (
    <div className="code-block-wrapper my-4 rounded-lg overflow-hidden border border-black/10">
      {/* Header with language and copy button */}
      <div className="flex items-center justify-between px-3 py-2 bg-[#f6f8fa] border-b border-black/10">
        <span className="text-xs font-normal text-zinc-600 uppercase tracking-wide">
          {language || "text"}
        </span>
        <button
          onClick={handleCopy}
          className="flex items-center gap-1.5 px-2 py-1 rounded text-xs font-normal text-zinc-600 
                     hover:bg-zinc-200/50 hover:text-zinc-900 transition-colors"
          aria-label={copied ? "Copied!" : "Copy code"}
        >
          {copied ? (
            <>
              <Check className="w-3.5 h-3.5 text-emerald-600" />
              <span className="text-emerald-600">Copied!</span>
            </>
          ) : (
            <>
              <Copy className="w-3.5 h-3.5" />
              <span>Copy</span>
            </>
          )}
        </button>
      </div>

      {/* Code content */}
      <div className="max-h-[600px] overflow-auto">
        <SyntaxHighlighter
          language={language || "text"}
          style={oneLight}
          customStyle={{
            margin: 0,
            padding: "1rem",
            fontSize: "0.875rem", /* 14px - matches text-sm */
            lineHeight: "1.6",
            background: "#ffffff",
          }}
          codeTagProps={{
            style: {
              fontFamily:
                'ui-monospace, SFMono-Regular, "SF Mono", Menlo, Consolas, monospace',
            },
          }}
        >
          {code}
        </SyntaxHighlighter>
      </div>
    </div>
  );
});

// Generate heading ID for anchor links
function generateHeadingId(children: React.ReactNode): string {
  const text = String(children).toLowerCase();
  return text
    .replace(/[^\w\s-]/g, "")
    .replace(/\s+/g, "-")
    .replace(/-+/g, "-")
    .trim();
}

export const MarkdownRenderer = memo(function MarkdownRenderer({
  content,
  className = "",
}: MarkdownRendererProps) {
  if (!content) return null;

  return (
    <div className={className}>
      <ReactMarkdown
        remarkPlugins={[remarkGfm]}
        components={{
          // Headings with anchor IDs
          h1: ({ children, ...props }) => {
            const id = generateHeadingId(children);
            return (
              <h1
                id={id}
                className="text-4xl font-semibold leading-tight mt-8 mb-4 text-zinc-900 tracking-tight"
                {...props}
              >
                {children}
              </h1>
            );
          },
          h2: ({ children, ...props }) => {
            const id = generateHeadingId(children);
            return (
              <h2
                id={id}
                className="text-3xl font-semibold leading-tight mt-6 mb-3 text-zinc-900 tracking-tight border-b border-zinc-200 pb-2"
                {...props}
              >
                {children}
              </h2>
            );
          },
          h3: ({ children, ...props }) => {
            const id = generateHeadingId(children);
            return (
              <h3
                id={id}
                className="text-2xl font-medium leading-tight mt-5 mb-3 text-zinc-900 tracking-tight"
                {...props}
              >
                {children}
              </h3>
            );
          },
          h4: ({ children, ...props }) => (
            <h4
              className="text-xl font-medium leading-tight mt-4 mb-2 text-zinc-900"
              {...props}
            >
              {children}
            </h4>
          ),
          h5: ({ children, ...props }) => (
            <h5
              className="text-lg font-medium leading-tight mt-3 mb-2 text-zinc-900"
              {...props}
            >
              {children}
            </h5>
          ),
          h6: ({ children, ...props }) => (
            <h6
              className="text-base font-medium leading-tight mt-3 mb-2 text-zinc-500 uppercase tracking-wider"
              {...props}
            >
              {children}
            </h6>
          ),

          // Paragraphs - light weight as base
          p: ({ children, ...props }) => (
            <p
              className="my-4 text-base leading-[1.7] text-text-primary font-light"
              {...props}
            >
              {children}
            </p>
          ),

          // Lists - consistent with paragraph styling
          ul: ({ children, ...props }) => (
            <ul className="my-3 pl-5 list-disc space-y-1.5" {...props}>
              {children}
            </ul>
          ),
          ol: ({ children, ...props }) => (
            <ol className="my-3 pl-5 list-decimal space-y-1.5" {...props}>
              {children}
            </ol>
          ),
          li: ({ children, ...props }) => (
            <li
              className="text-base leading-[1.7] text-text-primary marker:text-text-tertiary font-light"
              {...props}
            >
              {children}
            </li>
          ),

          // Task lists (GFM)
          input: ({ checked, ...props }) => (
            <input
              type="checkbox"
              checked={checked}
              readOnly
              className="mr-2 h-3.5 w-3.5 rounded border-zinc-300 text-zinc-900 focus:ring-zinc-900"
              {...props}
            />
          ),

          // Code blocks and inline code
          code: ({ className, children, ...props }) => {
            const match = /language-(\w+)/.exec(className || "");
            const language = match ? match[1] : "";
            const code = String(children).replace(/\n$/, "");

            // Block code (has language or multiple lines)
            if (language || code.includes("\n")) {
              return <CodeBlock language={language} code={code} />;
            }

            // Inline code
            return (
              <code
                className="px-1.5 py-0.5 text-[0.85em] font-mono rounded bg-surface-secondary text-text-primary border border-border-light"
                {...props}
              >
                {children}
              </code>
            );
          },

          pre: ({ children }) => <>{children}</>,

          // Blockquotes
          blockquote: ({ children, ...props }) => (
            <blockquote
              className="my-3 pl-4 border-l-2 border-purple-500 italic text-text-secondary bg-purple-50/30 py-2 rounded-r"
              {...props}
            >
              {children}
            </blockquote>
          ),

          // Links
          a: ({ href, children, ...props }) => (
            <a
              href={href}
              className="text-coral hover:underline underline-offset-2 decoration-coral/50"
              target={href?.startsWith("http") ? "_blank" : undefined}
              rel={href?.startsWith("http") ? "noopener noreferrer" : undefined}
              {...props}
            >
              {children}
            </a>
          ),

          // Images
          img: ({ src, alt, ...props }) => (
            <img
              src={src}
              alt={alt}
              className="my-4 max-w-full h-auto rounded-lg shadow-sm"
              loading="lazy"
              {...props}
            />
          ),

          // Horizontal rule
          hr: () => <hr className="my-6 border-zinc-200" />,

          // Tables (GFM)
          table: ({ children, ...props }) => (
            <div className="my-4 overflow-x-auto rounded-lg border border-zinc-200">
              <table
                className="min-w-full divide-y divide-zinc-200 text-sm"
                {...props}
              >
                {children}
              </table>
            </div>
          ),
          thead: ({ children, ...props }) => (
            <thead className="bg-zinc-50" {...props}>
              {children}
            </thead>
          ),
          tbody: ({ children, ...props }) => (
            <tbody className="divide-y divide-zinc-200 bg-white" {...props}>
              {children}
            </tbody>
          ),
          tr: ({ children, ...props }) => (
            <tr className="hover:bg-zinc-50/50 transition-colors" {...props}>
              {children}
            </tr>
          ),
          th: ({ children, ...props }) => (
            <th
              className="px-4 py-3 text-left text-sm font-medium text-text-secondary uppercase tracking-wider"
              {...props}
            >
              {children}
            </th>
          ),
          td: ({ children, ...props }) => (
            <td
              className="px-4 py-3 text-text-primary whitespace-nowrap"
              {...props}
            >
              {children}
            </td>
          ),

          // Strikethrough (GFM)
          del: ({ children, ...props }) => (
            <del className="line-through text-zinc-500" {...props}>
              {children}
            </del>
          ),

          // Strong and emphasis - decreased by one level
          strong: ({ children, ...props }) => (
            <strong className="font-medium text-zinc-900" {...props}>
              {children}
            </strong>
          ),
          em: ({ children, ...props }) => (
            <em className="italic" {...props}>
              {children}
            </em>
          ),
        }}
      >
        {content}
      </ReactMarkdown>
    </div>
  );
});

